<script lang="ts">
 import{onMount}from'svelte';
 import{request}from'#lib/client/api.ts';
 import ReferencePicker from'../ReferencePicker.svelte';
 type Choice={id:string;name:string;[key:string]:any};
 let{id,value='',initial=[],allowEmpty=true,onchange}:{id:string;value?:string;initial?:any[];allowEmpty?:boolean;onchange:(value:string)=>void}=$props();
 let resetCount=$state(0);let query=$state(''),manufacturer=$state(''),kind=$state(''),surface=$state(''),installation=$state(''),availability=$state('all'),minWidth=$state(''),maxWidth=$state(''),minDepth=$state(''),maxDepth=$state(''),minHeight=$state(''),maxHeight=$state(''),found:Choice[]|null=$state(null),known:Choice[]=$state([]),busy=$state(false),error=$state(''),more=$state(false),expanded=$state(false);
 const seeded=$derived(initial.map(p=>({...p,id:p.product_variant_version_id??p.version_id??p.id,name:p.name??p.manufacturer_sku??p.sku??'Produktstand'})));
 const options=$derived.by(()=>{const rows=found??seeded,selected=value?[...rows,...known,...seeded].find(p=>p.id===value):null;return[...(selected&&!rows.some(p=>p.id===value)?[selected]:[]),...rows,...(value&&!selected?[{id:value,name:'Gespeicherter Produktstand · Bezeichnung wird geprüft'}]:[])];});
 const selected=$derived(options.find(p=>p.id===value));
 const availabilityNames:Record<string,string>={available:'Laut gültiger Auskunft verfügbar',limited:'Laut gültiger Auskunft begrenzt verfügbar',unavailable:'Laut gültiger Auskunft nicht verfügbar',unknown:'Verfügbarkeit der konkreten Ausführung noch ungeklärt'};
 onMount(()=>{expanded=!seeded.length;if(value&&!seeded.some(p=>p.id===value))void search();});
 async function search(){if(busy)return;busy=true;error='';try{const filters:Record<string,string>={q:query,availability,...(value?{include_id:value}:{})};for(const[key,item]of Object.entries({manufacturer_id:manufacturer,product_kind:kind,surface_finish:surface,installation_type:installation,min_width_mm:minWidth,max_width_mm:maxWidth,min_depth_mm:minDepth,max_depth_mm:maxDepth,min_height_mm:minHeight,max_height_mm:maxHeight}))if(item.trim())filters[key]=item.trim();const result=await request('/api/v1/planning/products/search',filters);known=[...new Map([...known,...seeded,...result.items].map(p=>[p.id,p])).values()].slice(-300);found=result.items;more=result.possiblyMore;}catch(problem){error=(problem as Error).message;}finally{busy=false;}}
 function reset(){resetCount++;query='';manufacturer='';kind='';surface='';installation='';availability='all';minWidth='';maxWidth='';minDepth='';maxDepth='';minHeight='';maxHeight='';found=null;error='';more=false;}
</script>
<select {id} {value} required={!allowEmpty} onchange={event=>onchange(event.currentTarget.value)}><option value="" disabled={!allowEmpty}>{allowEmpty?'Freies Hüllmodell / kein Herstellerartikel':'Herstellerstand auswählen'}</option>{#each options as product}<option value={product.id}>{product.name}</option>{/each}</select>
{#if selected?.width_mm!==undefined}<div class="selected-product"><strong>{selected.manufacturer_name??'Eingefrorene Herstellerfassung'}</strong><p>{selected.manufacturer_sku??''} · {selected.width_mm} × {selected.depth_mm} × {selected.height_mm??'Höhe offen'} mm</p>{#if selected.status==='source_reference'}<p class="source-badge">Herstellerangabe · technische Prüfung offen</p><p>{selected.notes}</p>{#if selected.source_url}<a class="source-link" href={selected.source_url} target="_blank" rel="noreferrer">Originalquelle öffnen ↗</a>{/if}<p>Quellenstand: {selected.validation_report?.checkedOn??'siehe Quelle'} · {selected.validation_report?.locator??''}</p>{/if}<p>{availabilityNames[selected.availability_status??'unknown']}</p>{#if selected.availability_checked_on}<p>Auskunft vom {String(selected.availability_checked_on).slice(0,10)} · gültig bis {String(selected.availability_valid_until).slice(0,10)}{#if selected.available_quantity!==null&&selected.available_quantity!==undefined} · {selected.available_quantity} {selected.availability_unit}{/if}</p>{/if}</div>{/if}
<details class="product-search" bind:open={expanded}><summary>Hersteller, Maße und Ausführung filtern</summary><div class="filter-content"><label for={id+'-query'}>Name, Artikelnummer oder GTIN</label><input id={id+'-query'} type="search" maxlength="150" bind:value={query} onkeydown={event=>{if(event.key==='Enter'){event.preventDefault();void search();}}}/><label for={id+'-manufacturer'}>Hersteller</label>{#key resetCount}<ReferencePicker id={id+'-manufacturer'} reference="planning-manufacturers" value={manufacturer} onchange={value=>manufacturer=value}/>{/key}<label>Produktart<select bind:value={kind}><option value="">Alle Produktarten</option><option value="merchandise">Handelsprodukt</option><option value="raw_material">Rohmaterial</option><option value="stone_piece">Individuelles Werkstück</option><option value="service">Dienstleistung</option><option value="subcontract">Fremdleistung</option><option value="machine">Maschine</option><option value="transport">Transport</option><option value="flat_rate">Pauschalposition</option></select></label><div class="ranges">{#each [['Breite',()=>minWidth,(v:string)=>minWidth=v,()=>maxWidth,(v:string)=>maxWidth=v],['Tiefe',()=>minDepth,(v:string)=>minDepth=v,()=>maxDepth,(v:string)=>maxDepth=v],['Höhe',()=>minHeight,(v:string)=>minHeight=v,()=>maxHeight,(v:string)=>maxHeight=v]] as row}<label>{row[0]} ab (mm)<input inputmode="decimal" value={(row[1] as ()=>string)()} oninput={event=>(row[2] as (value:string)=>void)(event.currentTarget.value)}/></label><label>{row[0]} bis (mm)<input inputmode="decimal" value={(row[3] as ()=>string)()} oninput={event=>(row[4] as (value:string)=>void)(event.currentTarget.value)}/></label>{/each}</div><label>Oberfläche<input bind:value={surface} maxlength="150"/></label><label>Belegte Einbauart<input bind:value={installation} maxlength="150"/></label><label>Verfügbarkeit<select bind:value={availability}><option value="all">Alle, einschließlich unbekannter Verfügbarkeit</option><option value="available">Mit gültiger Verfügbarkeitsauskunft</option><option value="limited">Begrenzt verfügbar laut Auskunft</option><option value="unavailable">Nicht verfügbar laut Auskunft</option><option value="unknown">Noch ungeklärt oder Auskunft abgelaufen</option></select></label><div class="filter-actions"><button class="btn small" type="button" disabled={busy} onclick={search}>{busy?'Wird gesucht …':'Katalog durchsuchen'}</button><button class="btn small" type="button" disabled={busy} onclick={reset}>Filter zurücksetzen</button></div>{#if found}<p class="hint" role="status">{found.length} belegte Produktstände in der Auswahl oben.{more?' Für weitere Treffer die Suche genauer eingrenzen.':''} Ein bereits gespeicherter Stand bleibt unabhängig von den neuen Filtern sichtbar.</p>{/if}<p class="hint">Verfügbarkeit gilt für die konkrete Ausführung und den genannten Zeitraum. Eine Auskunft reserviert keine Ware und bestätigt keinen späteren Liefertermin.</p><a href="/product-availability" target="_blank" rel="noreferrer">Schriftliche Verfügbarkeitsauskünfte verwalten</a></div></details>{#if error}<p class="error" role="alert">{error}</p>{/if}
<style>.source-badge{font-weight:550;color:var(--warning)}.source-link{display:inline-block;color:var(--forest);min-height:32px;padding:5px 0}
select,input{display:block;box-sizing:border-box;width:100%;min-height:44px;padding:10px;margin-top:7px;border:1px solid var(--line);border-radius:4px;background:var(--paper);color:var(--ink);font:inherit;font-size:14px}label{display:block;font-size:13px;line-height:1.6;margin:15px 0 7px}.product-search{margin:10px 0 20px}.product-search>summary{font-size:12px;line-height:1.7;color:var(--forest);cursor:pointer;min-height:36px}.filter-content{padding:13px;border:1px solid var(--line);border-radius:4px;background:var(--paper);margin-top:8px}.filter-content>label:first-child{margin-top:0}.filter-content :global(select){min-height:44px;font-size:14px;width:100%;padding:10px;border:1px solid var(--line);background:var(--paper);color:var(--ink);border-radius:4px}.ranges{display:grid;grid-template-columns:1fr 1fr;gap:0 8px}.filter-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}.selected-product{margin:12px 0;padding:12px;background:var(--wash);border:1px solid var(--line);border-radius:4px;line-height:1.7;font-size:12px}.selected-product strong{font-size:13px}.selected-product p{margin:4px 0}.hint,a{font-size:12px;line-height:1.7;color:var(--muted)}.filter-content a{color:var(--forest)}.error{white-space:pre-wrap;padding:12px;color:var(--danger);border:1px solid var(--line);background:var(--danger-wash);font-size:12px}.btn{font-size:12px;min-height:44px}@media(max-width:720px){select,input,.filter-content :global(select){min-height:48px;font-size:16px}.btn,.product-search>summary{min-height:48px}}
</style>
